const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "DiaTool-DPO Research";
pres.title = "DiaTool-DPO: Enhancing Tool-Augmented LLM Dialogue via Direct Preference Optimization";
pres.subject = "Technical presentation for ML researchers and NLP engineers";

// ============================================================
// Color Palette: Midnight Executive (navy/ice blue/white)
// ============================================================
const C = {
  navy: "1E2761",
  ice: "CADCFC",
  white: "FFFFFF",
  slate: "334155",
  lightGray: "F1F5F9",
  midGray: "94A3B8",
  accentTeal: "0D9488",
  accentCoral: "F96167",
  accentGold: "F9E795"
};

// ============================================================
// Helper functions
// ============================================================
function addHeaderBar(slide, title) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 0.85,
    fill: { color: C.navy }
  });
  slide.addText(title, {
    x: 0.5, y: 0.18, w: 9, h: 0.55,
    fontSize: 28, bold: true, color: C.white,
    fontFace: "Calibri", valign: "middle"
  });
}

function addFooter(slide, pageNum) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: "100%", h: 0.175,
    fill: { color: C.ice }
  });
  slide.addText("DiaTool-DPO: Multi-Turn DPO for Tool-Augmented LLMs", {
    x: 0.5, y: 5.45, w: 8, h: 0.175,
    fontSize: 9, color: C.navy, fontFace: "Calibri", valign: "middle"
  });
  slide.addText(String(pageNum), {
    x: 9.2, y: 5.45, w: 0.5, h: 0.175,
    fontSize: 9, color: C.navy, fontFace: "Calibri", align: "right", valign: "middle"
  });
}

// ============================================================
// Slide 1: Title Slide
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Decorative accent bar left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: "100%",
    fill: { color: C.accentTeal }
  });

  slide.addText("DiaTool-DPO", {
    x: 0.7, y: 1.4, w: 8.5, h: 1.0,
    fontSize: 54, bold: true, color: C.white,
    fontFace: "Calibri", valign: "bottom"
  });

  slide.addText("Enhancing Tool-Augmented LLM Dialogue via Direct Preference Optimization", {
    x: 0.7, y: 2.45, w: 8.5, h: 0.7,
    fontSize: 22, color: C.ice,
    fontFace: "Calibri Light", valign: "top"
  });

  slide.addShape(pres.shapes.LINE, {
    x: 0.7, y: 3.2, w: 2.5, h: 0,
    line: { color: C.accentTeal, width: 3 }
  });

  slide.addText("A novel DPO-based method that models TA-LLM interactions as an MDP with 5 dialogue states and 3 query types, automatically constructing preference pairs to improve slot-filling and tool call rejection without human labeling.", {
    x: 0.7, y: 3.4, w: 8.0, h: 1.2,
    fontSize: 14, color: C.white,
    fontFace: "Calibri Light", valign: "top"
  });

  slide.addText("ML Researchers & NLP Engineers  |  RLHF & Tool-Augmented LLMs", {
    x: 0.7, y: 4.8, w: 8.0, h: 0.3,
    fontSize: 12, color: C.midGray,
    fontFace: "Calibri", valign: "middle"
  });
}

// ============================================================
// Slide 2: Problem & Motivation
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.white };
  addHeaderBar(slide, "SFT Alone Fails to Teach Slot-Filling and Tool Rejection");
  addFooter(slide, 2);

  // Left column: failure modes
  slide.addText("Failure Modes of SFT-Only Training", {
    x: 0.5, y: 1.1, w: 4.3, h: 0.4,
    fontSize: 16, bold: true, color: C.navy, fontFace: "Calibri"
  });

  const failures = [
    { icon: "❌", title: "Missing Follow-ups", desc: "Fails to ask clarifying questions when user queries lack required arguments." },
    { icon: "❌", title: "Hallucinated Tool Calls", desc: "Invokes tools with incomplete or fabricated slot values." },
    { icon: "❌", title: "No Rejection", desc: "Cannot refuse out-of-scope requests, leading to incorrect tool invocations." }
  ];

  failures.forEach((f, i) => {
    let y = 1.6 + i * 1.05;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: y, w: 4.3, h: 0.9,
      fill: { color: C.lightGray }, line: { color: C.ice, width: 1 }
    });
    slide.addText(f.icon, {
      x: 0.65, y: y + 0.05, w: 0.4, h: 0.4,
      fontSize: 18, align: "center", valign: "middle"
    });
    slide.addText(f.title, {
      x: 1.15, y: y + 0.05, w: 3.5, h: 0.35,
      fontSize: 14, bold: true, color: C.slate, fontFace: "Calibri"
    });
    slide.addText(f.desc, {
      x: 1.15, y: y + 0.38, w: 3.5, h: 0.45,
      fontSize: 12, color: C.slate, fontFace: "Calibri Light"
    });
  });

  // Right column: motivation
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: 1.1, w: 4.4, h: 3.55,
    fill: { color: C.navy }
  });

  slide.addText("Why DPO?", {
    x: 5.4, y: 1.3, w: 3.8, h: 0.4,
    fontSize: 18, bold: true, color: C.white, fontFace: "Calibri"
  });

  slide.addText([
    { text: "SFT learns from expert trajectories but cannot distinguish good vs. bad dialogue flows.", options: { breakLine: true } },
    { text: "", options: { breakLine: true } },
    { text: "DPO directly optimizes from paired preferences — chosen vs. rejected trajectories — without a separate reward model.", options: { breakLine: true } },
    { text: "", options: { breakLine: true } },
    { text: "Result: better slot-filling, fewer hallucinated calls, and robust tool rejection.", options: { breakLine: true } }
  ], {
    x: 5.4, y: 1.8, w: 3.8, h: 2.6,
    fontSize: 13, color: C.ice, fontFace: "Calibri Light",
    valign: "top", paraSpaceAfter: 6
  });

  // Bottom stat callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: 4.85, w: 4.4, h: 0.45,
    fill: { color: C.accentTeal }
  });
  slide.addText("Near GPT-4o performance on smaller open-source models", {
    x: 5.1, y: 4.85, w: 4.4, h: 0.45,
    fontSize: 12, bold: true, color: C.white,
    fontFace: "Calibri", align: "center", valign: "middle"
  });
}

// ============================================================
// Slide 3: Five-State MDP
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.white };
  addHeaderBar(slide, "Modeling TA-LLM Dialogue as a 5-State Markov Decision Process");
  addFooter(slide, 3);

  // Include figure 1
  const figPath = "/app/benchmark/assets/figure_1.jpg";
  if (fs.existsSync(figPath)) {
    slide.addImage({
      path: figPath,
      x: 0.5, y: 1.1, w: 4.6, h: 3.6,
      sizing: { type: "contain", w: 4.6, h: 3.6 }
    });
  }

  slide.addText("Figure 1: Five internal states and state trajectories for three query types", {
    x: 0.5, y: 4.75, w: 4.6, h: 0.3,
    fontSize: 10, color: C.midGray, fontFace: "Calibri Light", align: "center"
  });

  // State descriptions on right
  const states = [
    { num: "1", name: "Initial State", desc: "No history. Out-of-scope requests return a rejection message and remain here." },
    { num: "2", name: "Tool Selected w/o Complete Slots", desc: "Tool identified but required parameters missing. Slot-filling QA occurs here." },
    { num: "3", name: "Tool Selected w/ Complete Slots", desc: "Both tool selection and all argument values are determined." },
    { num: "4", name: "Wait for Tool Response", desc: "Tool call executed, awaiting results." },
    { num: "5", name: "Complete", desc: "Tool results received; completion message generated for the user." }
  ];

  states.forEach((s, i) => {
    let y = 1.1 + i * 0.82;
    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 5.3, y: y, w: 0.38, h: 0.38,
      fill: { color: C.accentTeal }
    });
    slide.addText(s.num, {
      x: 5.3, y: y, w: 0.38, h: 0.38,
      fontSize: 14, bold: true, color: C.white,
      align: "center", valign: "middle"
    });
    slide.addText(s.name, {
      x: 5.85, y: y, w: 3.8, h: 0.25,
      fontSize: 13, bold: true, color: C.navy, fontFace: "Calibri"
    });
    slide.addText(s.desc, {
      x: 5.85, y: y + 0.28, w: 3.8, h: 0.45,
      fontSize: 11, color: C.slate, fontFace: "Calibri Light"
    });
  });
}

// ============================================================
// Slide 4: Three Query Types
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.white };
  addHeaderBar(slide, "Three Query Types Define Distinct State Trajectories");
  addFooter(slide, 4);

  const tableData = [
    [
      { text: "Query Type", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
      { text: "State Trajectory", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
      { text: "Description", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
      { text: "Example", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } }
    ],
    [
      { text: "Type 1", options: { bold: true, fill: { color: C.lightGray }, color: C.navy, align: "center" } },
      { text: "1 → 3 → 4 → 5", options: { fill: { color: C.lightGray }, color: C.slate, align: "center" } },
      { text: "Query contains all required arguments. No slot-filling needed.", options: { fill: { color: C.lightGray }, color: C.slate } },
      { text: '"Check weather in Seoul today"', options: { fill: { color: C.lightGray }, color: C.slate } }
    ],
    [
      { text: "Type 2", options: { bold: true, fill: { color: C.ice }, color: C.navy, align: "center" } },
      { text: "1 → (2×N) → 3 → 4 → 5", options: { fill: { color: C.ice }, color: C.slate, align: "center" } },
      { text: "Query lacks some arguments. Slot-filling QA repeats N times until all required fields are gathered.", options: { fill: { color: C.ice }, color: C.slate } },
      { text: '"Book a flight" → "Where to?" → "Tokyo" → ...', options: { fill: { color: C.ice }, color: C.slate } }
    ],
    [
      { text: "Type 3", options: { bold: true, fill: { color: C.lightGray }, color: C.navy, align: "center" } },
      { text: "1 → 1", options: { fill: { color: C.lightGray }, color: C.slate, align: "center" } },
      { text: "Requested functionality is unavailable. Tool call must be rejected.", options: { fill: { color: C.lightGray }, color: C.slate } },
      { text: '"Translate this to Klingon" (no translation tool)', options: { fill: { color: C.lightGray }, color: C.slate } }
    ]
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 1.15, w: 9.0, h: 3.6,
    border: { pt: 0.5, color: C.midGray },
    colW: [1.4, 2.2, 3.2, 2.2],
    fontFace: "Calibri",
    fontSize: 12,
    valign: "middle"
  });

  // Bottom insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.95, w: 9.0, h: 0.4,
    fill: { color: C.navy }
  });
  slide.addText("These trajectories form the basis for automatic preference pair construction — no human labeling required.", {
    x: 0.5, y: 4.95, w: 9.0, h: 0.4,
    fontSize: 12, bold: true, color: C.white,
    fontFace: "Calibri", align: "center", valign: "middle"
  });
}

// ============================================================
