  addFooter(slide, 5);

  const tableData = [
    [
      { text: "Query", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
      { text: "Chosen Trajectory", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
      { text: "Rejected Trajectory", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
      { text: "Learning Lesson", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
      { text: "Count", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } },
      { text: "Difficulty", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "center" } }
    ],
    [
      { text: "Type 1", options: { bold: true, align: "center" } },
